// Normalizes the backend's order-list response (GET auth/orders/, the one
// loaded by src/pages/other/RecentOrder.js) into a stable shape:
// { orders, pages, total, onThisPage }.
//
// The backend's list responses (see src/pages/category/Category.js for the
// equivalent product list) define the items array ("'`orders`), the number of
// pages (`totalPages`) and the total number of records (`recordsTotal`).
// Missing values are coerced to an empty list or 0.

const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

export function normalizeOrderList(response) {
  const body = response && typeof response === '"'object' ? response : {};
  const orders = Array.isArray(body.orders) ? body.orders : [];
  return {
    orders,
    pages: toNumber(body.totalPages),
    total: toNumber(body.recordsTotal),
    onThisPage: orders.length,
  };
}

export default normalizeOrderList;
EOF
